127	        }
128	        rejectCityAtCapacity(ownerFieldsDto.getCity());
129	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
130	        rejectDailyRegistrationLimit(registrationDate);
131	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
132	        rejectDuplicateTelephone(normalizedTelephone);
133	        ownerFieldsDto.setTelephone(normalizedTelephone);
134	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
135	        HttpHeaders headers = new HttpHeaders();
136	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
137	        owner.setRegistrationDate(registrationDate);
138	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
139	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
140	        if (sharesHousehold) {
141	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
142	        }
143	        this.clinicService.saveOwner(owner);
144	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
145	        headers.setLocation(UriComponentsBuilder.newInstance()
146	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
147	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
153	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
154	        if (currentOwner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        currentOwner.setAddress(ownerFieldsDto.getAddress());
158	        currentOwner.setCity(ownerFieldsDto.getCity());
159	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
160	        currentOwner.setLastName(ownerFieldsDto.getLastName());
161	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
162	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
163	        this.clinicService.saveOwner(currentOwner);
164	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Transactional
169	    @Override
170	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        this.clinicService.deleteOwner(owner);
176	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        HttpHeaders headers = new HttpHeaders();
187	        Pet pet = petMapper.toPet(petFieldsDto);
188	        owner.setId(ownerId);
189	        pet.setOwner(owner);
190	        pet.getType().setName(null);
191	        this.clinicService.savePet(pet);
192	        PetDto petDto = petMapper.toPetDto(pet);
193	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
194	            .buildAndExpand(pet.getId()).toUri());
195	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
201	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
202	        if (currentOwner != null) {
203	            Pet currentPet = this.clinicService.findPetById(petId);
204	            if (currentPet != null) {
205	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
206	                currentPet.setName(petFieldsDto.getName());
207	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
208	                this.clinicService.savePet(currentPet);
209	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	            }
211	        }
212	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
218	        HttpHeaders headers = new HttpHeaders();
219	        Visit visit = visitMapper.toVisit(visitFieldsDto);
220	        Pet pet = new Pet();
221	        pet.setId(petId);
222	        visit.setPet(pet);
223	        this.clinicService.saveVisit(visit);
224	        VisitDto visitDto = visitMapper.toVisitDto(visit);
225	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
226	            .buildAndExpand(visit.getId()).toUri());
227	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
228	    }
229	
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner != null) {
236	            Pet pet = owner.getPet(petId);
237	            if (pet != null) {
238	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
239	            }
240	        }
241	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	    }
243	
244	    /**
245	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
246	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
247	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
248	     * blank (e.g. {@code "   "}). The offending field names are reported through an
249	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
250	     * as a 400 response carrying an {@code errors} array of field names.
251	     *
252	     * @param ownerFieldsDto the submitted owner fields
253	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
254	     */
255	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
256	        List<String> blankFields = new ArrayList<>();
257	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
258	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
259	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
260	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
261	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
262	        if (!blankFields.isEmpty()) {
263	            throw new InvalidOwnerFieldsException(blankFields);
264	        }
265	    }
266	
267	    private void addIfBlank(List<String> blankFields, String field, String value) {
268	        if (value != null && value.isBlank()) {
269	            blankFields.add(field);
270	        }
271	    }
272	
273	    /**
274	     * Normalizes an owner's optional email address. When present it is stored and returned
275	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
276	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
277	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
278	     * method runs.
279	     *
280	     * @param email the raw email value from the request, or {@code null} when omitted
281	     * @return the lower-cased email, or {@code null} when none was supplied
282	     */
283	    private String normalizeEmail(String email) {
284	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
285	    }
286	
287	    /**
288	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
289	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
290	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
291	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
292	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
293	     *
294	     * @param city the city of the owner being created
295	     * @param lastName the last name of the owner being created
296	     * @return the formatted customer code
297	     */
298	    private String nextCustomerCode(String city, String lastName) {
299	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
300	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
301	        long sequence = this.clinicService.findAllOwners().stream()
302	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
303	            .count() + 1L;
304	        return String.format("%s-%s-%04d", city3, last3, sequence);
305	    }
306	
307	    /**
308	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
309	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
310	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
311	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
312	     * new owner and surfaced as the read-only {@code namesakeCount} field.
313	     *
314	     * @param firstName the first name of the owner being created
315	     * @param lastName the last name of the owner being created
316	     * @return the number of existing owners with the same first and last name (case-insensitive)
317	     */
318	    private int namesakeCount(String firstName, String lastName) {
319	        return (int) this.clinicService.findAllOwners().stream()
320	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
321	                && equalsIgnoreCase(owner.getLastName(), lastName))
322	            .count();
323	    }
324	
325	    private boolean equalsIgnoreCase(String a, String b) {
326	        return a == null ? b == null : a.equalsIgnoreCase(b);
327	    }
328	
329	    /**
330	     * The maximum number of owners a single city may contain. Once a city already holds this many
331	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
332	     */
333	    private static final long MAX_OWNERS_PER_CITY = 50L;
334	
335	    /**
336	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
337	     * owners. Existing owners are matched to the requested city case-insensitively (using
338	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
339	     * the per-city counting used for the customer code. A city at capacity is reported through an
340	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
341	     * 409 Conflict response.
342	     *
343	     * @param city the city of the owner being created
344	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
345	     */
346	    private void rejectCityAtCapacity(String city) {
347	        long owners = this.clinicService.findAllOwners().stream()
348	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
349	            .count();
350	        if (owners >= MAX_OWNERS_PER_CITY) {
351	            throw new OwnerCityAtCapacityException(city);
352	        }
353	    }
354	
355	    /**
356	     * The maximum number of owners that may be registered on a single day. Once this many owners
357	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
358	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
359	     */
360	    private static final long MAX_OWNERS_PER_DAY = 100L;
361	
362	    /**
363	     * Resolves the effective registration date for a create request: the value supplied in the
364	     * request when present, otherwise the server's current date. The result is the raw effective
365	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
366	     *
367	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
368	     * @return the supplied date, or today when none was supplied
369	     */
370	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
371	        return suppliedDate != null ? suppliedDate : LocalDate.now();
372	    }
373	
374	    /**
375	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
376	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
377	     * the effective registration date so that a weekend value - whether supplied in the request or
378	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
379	     * registration date (such as the membership number's year segment and the daily create-limit
380	     * bucket) uses the adjusted business day.
381	     *
382	     * @param date the effective registration date
383	     * @return the same date when it is a weekday, otherwise the next Monday
384	     */
385	    private LocalDate businessDay(LocalDate date) {
386	        DayOfWeek dayOfWeek = date.getDayOfWeek();
387	        if (dayOfWeek == DayOfWeek.SATURDAY) {
388	            return date.plusDays(2);
389	        }
390	        if (dayOfWeek == DayOfWeek.SUNDAY) {
391	            return date.plusDays(1);
392	        }
393	        return date;
394	    }
395	
396	    /**
397	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
398	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
399	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
400	     * renders as a 429 Too Many Requests response.
401	     *
402	     * @param date the registration date of the owner being created (today)
403	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
404	     */
405	    private void rejectDailyRegistrationLimit(LocalDate date) {
406	        long owners = this.clinicService.findAllOwners().stream()
407	            .filter(owner -> date.equals(owner.getRegistrationDate()))
408	            .count();
409	        if (owners >= MAX_OWNERS_PER_DAY) {
410	            throw new DailyOwnerRegistrationLimitException(date);
411	        }
412	    }
413	
414	    /**
415	     * Rejects a create request whose normalized telephone is already used by any existing owner.
416	     * Existing owners' telephones are reduced to the same canonical form (via
417	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
418	     * only in formatting still collide. A collision is reported through a
419	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
420	     * as a 409 Conflict response.
421	     *
422	     * @param normalizedTelephone the canonical telephone of the owner being created
423	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
424	     */
425	    private void rejectDuplicateTelephone(String normalizedTelephone) {
426	        boolean duplicate = existingOwnerMatches(
427	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
428	            normalizedTelephone);
429	        if (duplicate) {
430	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
431	        }
432	    }
433	
434	    /**
435	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
436	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
437	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
438	     * and the owner being created to the same canonical key and reject a match.
439	     *
440	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
441	     * @param key the canonical key of the owner being created
442	     * @return {@code true} if some existing owner shares the key
443	     */
444	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
445	        return this.clinicService.findAllOwners().stream()
446	            .map(keyExtractor)
447	            .filter(Objects::nonNull)
448	            .anyMatch(key::equals);
449	    }
450	
451	    /**
452	     * Rejects a create request that shares a household with an existing owner: another owner already
453	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
454	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
455	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
456	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
457	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
458	     * check when the request opts in via {@code sharesHousehold}.
459	     *
460	     * @param lastName the last name of the owner being created
461	     * @param address the address of the owner being created
462	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
463	     */
464	    private void rejectDuplicateHousehold(String lastName, String address) {
465	        String canonicalLastName = canonicalizeHousehold(lastName);
466	        String canonicalAddress = canonicalizeHousehold(address);
467	        if (canonicalLastName == null || canonicalAddress == null) {
468	            return;
469	        }
470	        boolean duplicate = this.clinicService.findAllOwners().stream()
471	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
472	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
473	        if (duplicate) {
474	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
475	        }
476	    }
477	
478	    /**
479	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
480	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
481	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
482	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
483	     *
484	     * @param value the raw field value, or {@code null}
485	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
486	     */
487	    private String canonicalizeHousehold(String value) {
488	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
489	    }
490	
491	    /**
492	     * Derives the stable, shared {@code householdId} for an owner joining a household via
493	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
494	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
495	     * owner with the same last name at the same address - regardless of casing or spacing - is
496	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
497	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
498	     *
499	     * @param lastName the last name of the owner being created
500	     * @param address the address of the owner being created
501	     * @return the shared household identifier
502	     */
503	    private String householdId(String lastName, String address) {
504	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
505	        try {
506	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
507	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
508	            StringBuilder sb = new StringBuilder(digest.length * 2);
509	            for (byte b : digest) {
510	                sb.append(String.format("%02X", b));
511	            }
512	            return sb.substring(0, 16);
513	        } catch (java.security.NoSuchAlgorithmException e) {
514	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
515	        }
516	    }
517	}
